// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        address owner = c.owner();
        vm.assume(newOwner != owner);

        address caller = address(0xBEEF);
        vm.assume(caller != owner);

        vm.prank(caller);
        try c.setOwner(newOwner) {
            assertTrue(c.owner() == owner, "non-owner must not change owner");
        } catch {
            assertTrue(c.owner() == owner, "owner unchanged after revert");
        }
    }
}
